function parseSummaryCounts(output) {
  const normalizedOutput = stripAnsi(output);
  const matches = Array.from(
    normalizedOutput.matchAll(
      /svelte-check found\s+(\d+)\s+errors?\s+and\s+(\d+)\s+warnings?/gi
    )
  );

  if (matches.length === 0) {
