    vi.clearAllMocks();

    vi.mocked(resolveMutationQueryV2).mockReturnValue("MOCK_MUTATION_QUERY");
    vi.mocked(resolveSyncDownQuery).mockReturnValue("MOCK_SYNC_DOWN_QUERY");
  });

