    icon = null,
    size = Size.lg,
    phIconSize = Size.sm,
    isRenderRaw = false,
    isAccentBg = false,
    onclick = void 0
  }: any = $props();
  const tailwindSizes: any = {
    xxs: "w-2 h-2",
    xs: "w-3 h-3",
    sm: "w-4 h-4",
    md: "w-[1.25rem] h-[1.25rem]",
    lg: "w-6 h-6",
    xl: "w-8 h-8",
    xxl: "w-10 h-10",
    "5xl": "w-16 h-full",
    fit: "w-fit h-fit"
  };

  function importIcon(icon: string) {
    return import(`../icons/SVGIcons/${icon}.svg?raw`);
