import posthog from "posthog-js";
import { stringify } from "@21n/shared-utils/json.utils";
/** Installs telemetry error capture and returns its lifecycle cleanup. */
export function installPosthogTelemetry() {
  initializePosthog(import.meta.env.VITE_POSTHOG_PROJECT_KEY);
  window.addEventListener("errorLog", handleError as EventListener);
  return () => {
    window.removeEventListener("errorLog", handleError as EventListener);
    posthog.reset();
  };
}

function initializePosthog(projectKey: string) {
  if (!projectKey) return;
  posthog.init(projectKey, {
    api_host: "https://us.i.posthog.com",

    session_recording: {
      maskTextSelector: ".email, .sensitive, .userdata"
    }
  });
}

function handleError(error: any) {
  try {
    posthog.captureException(
      error.detail?.message
        ? typeof error.detail.message === "string"
          ? error.detail.message
          : stringify(error.detail.message)
        : (error.detail?.error ?? error.detail?.message?.error ?? "Error")
    );
  } catch (e) {
    console.error("Error capturing error", e);
  }
}
import { isExtensionEnvironment } from "@21n/shared-utils/browser-environment";
import { bundleNumber } from "@21n/ui/icons/icons-list";
import { iconMappings, type IconSet } from "@21n/ui/icons/icons.map";
import { resolveElementAssetPath } from "@21n/ui/environment/element-environment.store";

export const spriteVersion = bundleNumber;
export const extensionSprites = new Map<string, string>();

export function getIconFromMapping(
  genericName: string,
  iconSet: IconSet
): string | null {
  const mapping = iconMappings[genericName];
  if (!mapping) return null;

  return mapping[iconSet] || mapping.phosphor;
}

export function resolveGenericIcon(genericName: string): string {
  let iconSet: IconSet = "phosphor";

  const resolvedIcon = getIconFromMapping(genericName, iconSet);
  if (resolvedIcon) {
    if (resolvedIcon.includes(":")) return resolvedIcon;
    if (iconSet === "phosphor") {
      return `ph:${resolvedIcon}-light`;
    }
    if (iconSet === "lucide") {
      return `lucide:${resolvedIcon}`;
    }
    if (iconSet === "solar") {
      return `solar:${resolvedIcon}-line-duotone`;
    }
  }
  return genericName;
}

export function cleanExtensionSprites() {
  extensionSprites.forEach((url: any) => URL.revokeObjectURL(url));
}

export function resolveSpriteSheetPath(sheet: string) {
  if (isExtensionEnvironment()) {
    return `assets/icons/${sheet}.svg`;
  }
  return resolveElementAssetPath(`icons/${sheet}-v${spriteVersion}.svg`);
}
/**
 * TODO - test the reliability of this function
 * @returns true if the current environment is an extension environment
 */
export function isExtensionEnvironment() {
  if (typeof chrome !== "undefined" && chrome?.runtime?.id) {
    return true;
  }

  if (
    typeof window !== "undefined" &&
    typeof (window as any)?.browser !== "undefined" &&
    (window as any).browser.runtime?.id
  ) {
    return true;
  }

  if (
    typeof window !== "undefined" &&
    typeof (window as any)?.__plasmo !== "undefined"
  ) {
    return true;
  }

  if (
    typeof window !== "undefined" &&
    (window.location.protocol === "chrome-extension:" ||
      window.location.protocol === "moz-extension:")
  ) {
    return true;
  }

  return false;
}

export function isContentScript(): boolean {
  try {
    return (
      typeof window !== "undefined" &&
      window.location.protocol !== "chrome-extension:"
    );
  } catch {
    return false;
  }
}
