        if (!url) throw new Error(`Live module missing: ${name}`);
        return import(url);
      };
      const { datafn } = await loaded("datafn/datafn.store");
      const id = `node:recent_boundary_${Date.now()}`;
      await datafn.node.mutate({
        operation: "insert",
