import { chromium, expect } from '@playwright/test';
const browser=await chromium.launch({channel:'chrome',headless:true,args:['--host-resolver-rules=MAP local.nucleum.app 127.0.0.1, MAP account-insouth-local.nucleum.app 127.0.0.1']});
const context=await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:780,height:600}});
await context.addInitScript(()=>localStorage.setItem('offlineSessionId',crypto.randomUUID()));
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(e.message));
try{
 await page.goto('https://local.nucleum.app/settings',{waitUntil:'domcontentloaded'});
 const appearance=page.getByRole('button',{name:'Appearance',exact:true});
 await expect(appearance).toBeVisible({timeout:30000});
 await appearance.click();
 await expect(page).toHaveURL(/setting=appearance-settings/);
 await expect(appearance).toHaveClass(/bg-aps3/);
 await expect(page.getByText('Appearance',{exact:true}).last()).toBeVisible();
 const dateTime=page.getByRole('button',{name:'Date & Time',exact:true});
 await dateTime.click();
 await expect(page).toHaveURL(/setting=datetime-settings/);
 await expect(dateTime).toHaveClass(/bg-aps3/);
 await expect(appearance).not.toHaveClass(/bg-aps3/);
 await expect(page.getByText('Date & Time',{exact:true}).last()).toBeVisible();
 await page.reload({waitUntil:'domcontentloaded'});
 await expect(dateTime).toHaveClass(/bg-aps3/,{timeout:20000});
 await expect(page.getByText('Date & Time',{exact:true}).last()).toBeVisible();
 await page.setViewportSize({width:600,height:900});
 await expect(page.getByText('Date & Time',{exact:true}).last()).toBeVisible();
 await page.reload({waitUntil:'domcontentloaded'});
 await expect(page.getByText('Date & Time',{exact:true}).last()).toBeVisible({timeout:20000});
 console.log('Settings landscape selection, headings, reload, and portrait heading: passed.');
 console.log('Page errors:',errors.length);
}catch(e){console.log('Settings smoke failed:',e.message);console.log('URL path:',new URL(page.url()).pathname);console.log('Page errors:',errors.length);process.exitCode=1;}finally{await browser.close();}
