 await p.setViewportSize({width:600,height:900});await expect(p.getByText('Date & Time',{exact:true}).last()).toBeVisible();await p.reload({waitUntil:'domcontentloaded'});await expect(p.getByText('Date & Time',{exact:true}).last()).toBeVisible({timeout:30000});
