  const owner = Symbol("dnd-page-owner");
  dndPageOwners.add(owner);
  syncDnDPageState();
  let isReleased = false;
  return () => {
    if (isReleased) return;
    isReleased = true;
    dndPageOwners.delete(owner);
    syncDnDPageState();
  };
}

